#construct the model-ready dataset from the prepared country-month panel
library(data.table)

#load shared paths and forecasting settings
source("scripts/00_config.R")

#load the prepared panel generated by script 01
panel <- as.data.table(
  readRDS(config$paths$prepared_panel)
)

#sort observations chronologically within each country
panel <- panel[order(country, month)]

#check the first month, last month and observation count for each sample
panel[
  , .(
    first_month = min(month),
    last_month = max(month),
    observations = .N
  ),
  by = sample
]

#display country-month combinations appearing more than once
panel[, .N, by = .(country, month)][N > 1]

#convert YYYY-MM dates into consecutive integer month IDs
panel[
  , month_id :=
    as.integer(substr(month, 1, 4)) * 12 +
    as.integer(substr(month, 6, 7))
]

#calculate the gap between consecutive observations within each country
panel[
  , month_gap := c(NA, diff(month_id)),
  by = country
]

#display missing or irregular monthly intervals (expected: zero rows)
panel[
  !is.na(month_gap) & month_gap != 1,
  .(country, month, month_gap)
]

#shift the retail index by one month within each country
panel[
  , retail_index_previous := c(NA, retail_index[-.N]),
  by = country
]

#calculate monthly log retail growth (see Technical Report, Section 2.2)
panel[
  , retail_growth :=
    100 * log(retail_index / retail_index_previous)
]

#check missing growth values and nonpositive retail indices by country
panel[
  sample == "training",
  .(
    observations = .N,
    missing_growth = sum(is.na(retail_growth)),
    nonpositive_index = sum(retail_index <= 0, na.rm = TRUE)
  ),
  by = country
]

#apply predictor publication lags (see Technical Report, Section 3.2)
#shift retail growth by 3 months within each country
panel[
  , retail_growth_lag3 := c(
    NA, NA, NA,
    retail_growth[-c(.N - 2, .N - 1, .N)]
  ),
  by = country
]

#shift annual headline inflation by 2 months within each country
panel[
  , inflation_lag2 := c(
    NA,
    NA,
    inflation_yoy[-c(.N - 1, .N)]
  ),
  by = country
]

#shift unemployment by 3 months within each country
panel[
  , unemployment_lag3 := c(
    NA,
    NA,
    NA,
    unemployment_rate[-c(.N - 2, .N - 1, .N)]
  ),
  by = country
]

#load quarterly GDP growth and monthly-equivalent rates from script 01
gdp <- as.data.table(
  readRDS(
    file.path(config$paths$processed, "gdp_quarterly.rds")
  )
)

#convert GDP quarter-end dates into numeric month IDs
gdp[
  , quarter_end_month_id :=
    as.integer(substr(quarter_end, 1, 4)) * 12 +
    as.integer(substr(quarter_end, 6, 7))
]

#first eligible GDP forecast month: quarter-end plus 4 months (Report Section 3.2)
gdp[
  , available_forecast_month_id := quarter_end_month_id + 4
]

#initialize the GDP predictor and its source-quarter identifier
panel[, gdp_available := NA_real_]
panel[, gdp_source_quarter := NA_character_]

#assign the latest eligible GDP observation to each country-month
for (i in 1:nrow(panel)) {
  
  #filter GDP records by country and forecast availability
  eligible <- gdp[
    country == panel$country[i] &
      available_forecast_month_id <= panel$month_id[i]
  ]
  
  #sort eligible GDP quarters chronologically
  eligible <- eligible[order(quarter_end_month_id)]
  
  #proceed only if at least one eligible GDP quarter exists
  if (nrow(eligible) > 0) {
    
    #select the most recent eligible quarter
    latest <- nrow(eligible)
    
    #store the selected GDP value and its source quarter
    panel$gdp_available[i] <-
      eligible$gdp_monthly_equivalent[latest]
    
    panel$gdp_source_quarter[i] <-
      eligible$quarter[latest]
  }
}

#load weighted UCDP Candidate event records from script 01
candidate_conflict <- as.data.table(
  readRDS(
    file.path(
      config$paths$processed,
      "ucdp_candidate_exposure_events.rds"
    )
  )
)

#load Candidate release inventory and availability dates
candidate_sources <- as.data.table(
  readRDS(
    file.path(
      config$paths$processed,
      "ucdp_candidate_sources.rds"
    )
  )
)

#select distinct validation and testing months for Candidate predictors
forecast_months <- sort(unique(
  panel[
    sample %in% c("validation", "testing"),
    month_id
  ]
))

#initialize a list to store monthly Candidate exposure tables
conflict_results <- list()

#construct Candidate conflict exposure separately for each target month
for (i in 1:length(forecast_months)) {
  
  target_month <- forecast_months[i]
  #use events from two months before the forecast target
  reference_month <- target_month - 2
  
  # A missing source file must not be interpreted as zero conflict.
  if (!(reference_month %in% candidate_sources$source_month_id)) {
    stop("Candidate source missing for month ID: ", reference_month)
  }
  
  #retain event records from releases eligible by the target month
  eligible <- candidate_conflict[
    available_forecast_month_id <= target_month
  ]
  
  #sort events by release month and retain the latest eligible version
  #for each focal country and event ID
  eligible <- eligible[order(source_month_id)]
  
  eligible <- eligible[
    , .SD[.N],
    by = .(focal_country, id)
  ]
  
  #keep events whose recorded start month matches the t-2 reference month
  eligible <- eligible[
    event_month_id == reference_month
  ]
  
  #sum the four event-level exposure measures by focal country
  monthly_exposure <- eligible[
    , .(
      conflict_500_lag2 = sum(weight_500),
      conflict_1000_lag2 = sum(weight_1000),
      conflict_2000_lag2 = sum(weight_2000),
      conflict_deaths_1000_lag2 = sum(deaths_weight_1000)
    ),
    by = focal_country
  ]
  
  #assign the exposure values to their forecast target month
  monthly_exposure[, month_id := target_month]
  #store this month's exposure table for later combination
  conflict_results[[i]] <- monthly_exposure
}

#combine all monthly Candidate exposure tables into one dataset
candidate_predictors <- rbindlist(conflict_results)

#rename focal_country to match the main panel's country column
setnames(candidate_predictors, "focal_country", "country")

#left-join Candidate predictors by country and target month
panel <- merge(
  panel,
  candidate_predictors,
  by = c("country", "month_id"),
  all.x = TRUE
)

#load monthly conflict exposure aggregated from annual GED 23.1
annual_conflict <- as.data.table(
  readRDS(
    file.path(
      config$paths$processed,
      "ucdp_annual_exposure_monthly.rds"
    )
  )
)

#define the four original conflict-exposure column names
conflict_columns <- c(
  "conflict_500",
  "conflict_1000",
  "conflict_2000",
  "conflict_deaths_1000"
)

#generate standard lag-2 predictor names
lagged_columns <- paste0(conflict_columns, "_lag2")
#generate temporary names for annual GED predictors
annual_columns <- paste0(conflict_columns, "_annual_lag2")

#shift annual GED exposure from event month M to target month M+2
annual_conflict[
  , month_id :=
    as.integer(substr(month, 1, 4)) * 12 +
    as.integer(substr(month, 6, 7)) + 2
]

#rename annual exposure columns to avoid conflicts with Candidate columns
setnames(
  annual_conflict,
  conflict_columns,
  annual_columns
)

#retain country, shifted target month and annual exposure measures
annual_conflict <- annual_conflict[
  , c("country", "month_id", annual_columns),
  with = FALSE
]

#left-join annual GED exposure into the country-month panel
panel <- merge(
  panel,
  annual_conflict,
  by = c("country", "month_id"),
  all.x = TRUE
)

#use annual GED predictors for training; preserve Candidate values elsewhere
panel[
  sample == "training",
  (lagged_columns) := .SD,
  .SDcols = annual_columns
]

#initialize the conflict data-source identifier
panel[, conflict_source := NA_character_]

#label training observations with nonmissing annual GED exposure
panel[
  sample == "training" &
    !is.na(conflict_1000_lag2),
  conflict_source := "annual_GED_23.1"
]

#label validation and testing observations with nonmissing Candidate exposure
panel[
  sample %in% c("validation", "testing") &
    !is.na(conflict_1000_lag2),
  conflict_source := "monthly_Candidate"
]

#remove temporary annual columns after transferring their values
panel[, (annual_columns) := NULL]
#restore country-month ordering after the merges
panel <- panel[order(country, month)]

#summarize conflict-source coverage and missing exposure by sample
panel[
  , .(
    observations = .N,
    missing_conflict = sum(is.na(conflict_1000_lag2))
  ),
  by = .(sample, conflict_source)
]

#define the identifiers, target, predictors and provenance columns to retain
analysis_columns <- c(
  "country",
  "month",
  "month_id",
  "sample",
  "retail_growth",
  "retail_growth_lag3",
  "inflation_lag2",
  "unemployment_lag3",
  "gdp_available",
  "gdp_source_quarter",
  lagged_columns,
  "conflict_source"
)

#create the analysis panel with only the selected columns
analysis_panel <- panel[
  , analysis_columns,
  with = FALSE
]

#define the target and predictor variables required for complete-case filtering
model_variables <- c(
  "retail_growth",
  "retail_growth_lag3",
  "inflation_lag2",
  "unemployment_lag3",
  "gdp_available",
  lagged_columns
)

#flag rows with no missing values across the required model variables
usable <- complete.cases(
  analysis_panel[, model_variables, with = FALSE]
)

#retain incomplete observations for inspection
excluded_rows <- analysis_panel[!usable]

#display excluded row counts and date ranges by country and sample
print(
  excluded_rows[
    , .(
      excluded = .N,
      first_month = min(month),
      last_month = max(month)
    ),
    by = .(country, sample)
  ]
)

#stop if any validation or testing rows have missing model inputs or outcomes
if (any(excluded_rows$sample %in% c("validation", "testing"))) {
  stop(
    "Missing model inputs or outcomes in validation/testing. ",
    "Inspect excluded_rows before continuing."
  )
}

#retain only complete observations for model estimation and evaluation
model_panel <- analysis_panel[usable]

#save the full analysis panel, including incomplete rows
saveRDS(
  analysis_panel,
  config$paths$analysis_panel
)

#save the complete-case modeling panel for script 03
saveRDS(
  model_panel,
  config$paths$model_panel
)

#save excluded observations for missing-data diagnostics
saveRDS(
  excluded_rows,
  config$paths$excluded_model_rows
)